// TH18 st02bs Boss2, source reset t0 at card frame 124.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;
xformdef RICE_MOTION(omega: angle) {
    offscreen_keep(200);
    set_ang_vel(omega);
    @200 set_accel(0.02fx);
    set_ang_vel(0bam);
    set_accel(0fx);
}
xformdef BALL_MOTION(target: fx) {
    @60 set_accel((target-3fx)/60);
    set_accel(0fx);
}
sub rice_fan(center: angle, n: int, gap: int) {
    for i in 0..n {
        var off: int = ((i+1)/2)*gap;
        if n%2 == 0 { off = (2*(i/2)+1)*gap/2; }
        if i%2 != 0 { off = -off; }
        sh_angle(0, center+(off as angle), 0deg);
        sh_fire(0);
    }
}
sub rice_attack(start: int, turn: int, omega: angle) {
    var rank: int = global(GVAR_RANK);
    var n: int = 13;
    var gap: int = 4551; // 0.436332 radians
    if rank == 0 { n = 8; gap = 4915; }
    if rank == 3 { n = 15; }
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 10);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx);
    sh_xform(0, RICE_MOTION(omega));
    for j in 0..13 {
        if $frame >= self_int(1) { return; }
        rice_fan((start-j*turn) as angle, n, gap);
        card_wait(9);
    }
}
async sub balls() {
    var rank: int = global(GVAR_RANK);
    var n: int = 8;
    var times: int = 1;
    var target: fx = 0.8fx;
    if rank == 1 { n = 10; }
    if rank == 2 { n = 20; times = 3; target = 1fx; }
    if rank == 3 { n = 26; times = 5; target = 1.6fx; }
    sh_reset(2);
    sh_sprite(2, TH18_BIG_BALL2, 3);
    sh_aim(2, 1);
    sh_ring(2, 1);
    sh_count(2, n, 1);
    sh_speed(2, 3fx, 0fx);
    sh_angle(2, 0deg, 30deg);
    sh_dist(2, -12fx);
    sh_xform(2, BALL_MOTION(target));
    for i in 0..times {
        if $frame >= self_int(1) { return; }
        sh_fire(2);
        if i+1 < times { wait(40); }
    }
}
async sub pattern() {
    wait(120);
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    wait(120);
    loop {
        if $frame >= self_int(1) { return; }
        rice_attack(32768, 4915, 182bam);
        if $frame >= self_int(1) { return; }
        spawn balls();
        card_move_rand();
        card_wait(10);
        if $frame >= self_int(1) { return; }
        rice_attack(0, -4915, -182bam);
        if $frame >= self_int(1) { return; }
        spawn balls();
        card_move_rand();
        card_wait(10);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 Boss2: movement state int0=step, int1=end; fx0/1=direction.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -80fx { nx = -80fx; }
    if nx > 80fx { nx = 80fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -40fx {
        a = r/3;
    } else if $self_x > 40fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
